  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val RequestFreshnessPriorityOwner_mining_guard_process_request_freshness_priority_owner_id = Arch.OreHoldMiningGuardSupervisorSystem_Instance_mining_guard_process_request_freshness_priority_owner.id
