    val GuardReportingDerivationOwner_mining_guard_process_guard_reporting_derivation_owner_id = Arch.OreHoldMiningGuardSupervisorSystem_Instance_mining_guard_process_guard_reporting_derivation_owner.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case RequestFreshnessPriorityOwner_mining_guard_process_request_freshness_priority_owner_id =>
          val prefix = "RequestFreshnessPriorityOwner_mining_guard_process_request_freshness_priority_owner_RM_TestSuite"
