          val testSuite =
            st"""package scp_candidate.Ore_Hold_Mining_Guard_Supervisor
                |
                |import org.sireum._
                |import scp_candidate.Ore_Hold_Mining_Guard_Supervisor._
                |
                |class ${suiteName} extends RequestFreshnessPriorityOwner_mining_guard_process_request_freshness_priority_owner_ScalaTest {
